{
  "findings": [
    {
      "check_id": "CKV_AWS_53",
      "title": "Ensure S3 bucket has block public ACLS enabled",
      "resource": "aws_s3_bucket_public_access_block.document_storage",
      "severity": "CRITICAL",
      "explanation": "The aws_s3_bucket_public_access_block resource is missing the block_public_acls attribute."
    }
  ],
  "patched_code": "resource \"aws_s3_bucket_public_access_block\" \"document_storage\" {\n  bucket = aws_s3_bucket.document_storage.id\n  block_public_acls       = true\n  block_public_policy     = true\n  ignore_public_acls      = true\n  restrict_public_buckets = true\n}",
  "fix_summary": "Added the missing block_public_acls attribute and set it to true."
}
